@js:
var key = "TRHvYbpGlNFoOdLaXrKRYgvdGwGfjnJj";
var iv = "kBKXQIpFYTDOHGLQlRUklPLtNPcBKSve".slice(0, 16);
var cipher = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", key, iv);
var hh = baseUrl.split(",")[1];
var maxPageLimit = 10; // 防止死循环
var currentPage = 1;
var nextUrl = baseUrl;
var allImages = [];

while (currentPage <= maxPageLimit) {
  try {
    var resp;
    if (currentPage === 1) {
      resp = result;
    } else {
      resp = java.ajax(nextUrl);
      if (!resp) break;
    }
    var rawData = JSON.parse(resp).data;
    if (!rawData) break;
    var images = JSON.parse(cipher.decryptStr(rawData));

    if (!images || images.length == 0) break;
    images.forEach(c => allImages.push(`<img src="${c.img},${hh}">`));
  } catch (e) {
    java.log(`第${currentPage}页处理失败: ${e.toString()}`);
  }

  currentPage++;
  nextUrl = nextUrl.replace(/page=(\d+)/, (_, p) => `page=${+p + 1}`);
}

allImages.join("\n");

